  };

  function pickTheme(cond) {
    var c = String(cond || "").toLowerCase();
    var keys = Object.keys(THEMES);
    for (var i = 0; i < keys.length; i++) {
      if (c.indexOf(keys[i]) !== -1) return THEMES[keys[i]];
    }
    return { icon: "🌡️", top: "#4a90d9", bottom: "#6db3f2" };
  }

  function num(v, fallback) {
    return (typeof v === "number" && isFinite(v)) ? v : fallback;
  }

  function setText(id, txt) {
    var el = document.getElementById(id);
    if (el) el.textContent = txt;
  }

  function render(d) {
    var unit = d.unit === "C" ? "C" : (d.unit || "F");
    var t = pickTheme(d.condition);

    document.documentElement.style.setProperty("--bg-top", t.top);
    document.documentElement.style.setProperty("--bg-bottom", t.bottom);
    document.getElementById("icon").textContent = t.icon;

