      try { render(merge(DEFAULT, msg.data)); } catch (_) {}
    }
  });

  // Optionally read data embedded by the host in a <script type="application/json" id="weather-data">.
  var embedded = null;
  var node = document.getElementById("weather-data");
  if (node) {
    try { embedded = JSON.parse(node.textContent); } catch (_) {}
  }

  render(merge(DEFAULT, embedded));
})();
